public abstract class Forma {
    abstract double calcularArea();
    void mostrarArea() { System.out.println("Area: " + calcularArea()); }
}

public class Circulo extends Forma {
    double radio;
    Circulo(double radio) { this.radio = radio; }
    @Override
    double calcularArea() { return Math.PI * radio * radio; }
}

public class Cuadrado extends Forma {
    double lado;
    Cuadrado(double lado) { this.lado = lado; }
    @Override
    double calcularArea() { return lado * lado; }
}

public class Main {
    public static void main(String[] args) {
        Forma[] formas = { new Circulo(5), new Cuadrado(4) };
        for (Forma f : formas) {
            f.mostrarArea();
        }
    }
}

