public abstract class MetodoPago {
    String nombre;
    MetodoPago(String nombre) { this.nombre = nombre; }

    abstract boolean procesar(double monto);
    abstract double calcularRecargo(double monto);
    String getTipo() { return "Metodo base"; }
}

public class TarjetaCredito extends MetodoPago {
    TarjetaCredito(String nombre) { super(nombre); }

    @Override
    boolean procesar(double monto) {
        System.out.println("Processing card " + nombre + ": $" + monto);
        return true;
    }

    @Override
    double calcularRecargo(double monto) { return monto * 0.035; }

    @Override
    String getTipo() { return "Tarjeta de credito"; }
}

public class Transferencia extends MetodoPago {
    Transferencia(String nombre) { super(nombre); }

    @Override
    boolean procesar(double monto) {
        System.out.println("Transfer from " + nombre + ": $" + monto);
        return true;
    }

    @Override
    double calcularRecargo(double monto) { return 0; }

    @Override
    String getTipo() { return "Transferencia bancaria"; }
}

public class PayPal extends MetodoPago {
    PayPal(String nombre) { super(nombre); }

    @Override
    boolean procesar(double monto) {
        System.out.println("PayPal payment " + nombre + ": $" + monto);
        return true;
    }

    @Override
    double calcularRecargo(double monto) { return monto * 0.02; }

    @Override
    String getTipo() { return "PayPal"; }
}

public class Main {
    static void procesarPago(MetodoPago metodo, double monto) {
        boolean ok = metodo.procesar(monto);
        double recargo = metodo.calcularRecargo(monto);
        double total = monto + recargo;
        System.out.println("  Surcharge: $" + recargo + " | Total: $" + total);
        if (metodo instanceof TarjetaCredito) {
            System.out.println("  Requires OTP verification");
        } else if (metodo instanceof Transferencia) {
            System.out.println("  No additional commission");
        } else if (metodo instanceof PayPal) {
            System.out.println("  Buyer protection active");
        }
    }

    public static void main(String[] args) {
        MetodoPago[] pagos = {
            new TarjetaCredito("Visa 1234"),
            new Transferencia("Cuenta 5678"),
            new PayPal("usuario@email.com")
        };
        double monto = 1000.0;
        for (MetodoPago mp : pagos) {
            procesarPago(mp, monto);
            System.out.println();
        }
    }
}
